// diffhtml は、HTML のファイルに書いたマークのコメントを、差分を表示する HTML に置き換える。
//
// review-triage-fix が説明の HTML (選択待ちの問題を判断するためのものと、直した問題を確認するためのもの) を
// 作るときに使う。差分の文字列をモデルにコピーさせず、記録 YAML の案のパッチと git のコミットから取るためのツール。
// マークの形・置き換え方・使い方の SSOT は README.md。
//
// 使い方:
//
//	go run -C <展開先>/tools/diffhtml . -html <HTML の絶対パス> -record <記録 YAML の絶対パス> -root <リポジトリのルートの絶対パス>
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(args []string) error {
	fs := flag.NewFlagSet("diffhtml", flag.ContinueOnError)
	htmlPath := fs.String("html", "", "マークを書いた HTML のファイル (絶対パス。必須)。成功したときだけ上書きする")
	recordPath := fs.String("record", "", "記録 YAML (絶対パス。必須)。案のパッチのマークはここから取る")
	root := fs.String("root", "", "リポジトリのルート (絶対パス。必須)。コミットのマークは、ここで git show を実行して取る")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if fs.NArg() > 0 {
		return fmt.Errorf("余分な引数があります: %s", strings.Join(fs.Args(), " "))
	}
	if err := requireAbsFile("-html", *htmlPath); err != nil {
		return err
	}
	if err := requireAbsFile("-record", *recordPath); err != nil {
		return err
	}
	if *root == "" || !filepath.IsAbs(*root) {
		return errors.New("-root にリポジトリのルートの絶対パスを渡してください")
	}
	if st, err := os.Stat(*root); err != nil || !st.IsDir() {
		return fmt.Errorf("-root が実在するディレクトリではありません: %s", *root)
	}

	src, err := os.ReadFile(*htmlPath)
	if err != nil {
		return err
	}
	rec, err := loadRecord(*recordPath)
	if err != nil {
		return err
	}
	out, err := fill(string(src), sources{record: rec, git: gitRunner{root: *root}})
	if err != nil {
		return fmt.Errorf("%s を変えずに終了します:\n%w", *htmlPath, err)
	}
	return writeAtomic(*htmlPath, []byte(out))
}

func requireAbsFile(name, path string) error {
	if path == "" || !filepath.IsAbs(path) {
		return fmt.Errorf("%s に絶対パスを渡してください", name)
	}
	st, err := os.Stat(path)
	if err != nil || st.IsDir() {
		return fmt.Errorf("%s が実在するファイルではありません: %s", name, path)
	}
	return nil
}

// writeAtomic は、同じディレクトリの一時ファイルに書いてから名前を替える。途中で失敗しても、
// 元の HTML が半分だけ書かれた状態で残らないようにするため。
func writeAtomic(path string, data []byte) error {
	st, err := os.Stat(path)
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".diffhtml-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), st.Mode().Perm()); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}
package main

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// marker は、HTML に書いたマークのコメント 1 つ。kind が "patch" なら run・problem・option で記録 YAML の
// 案のパッチを、"commit" なら sha でコミットを指す。
type marker struct {
	kind    string
	run     int
	problem string
	option  string
	sha     string
}

// markerRe は、マークの候補になるコメント。review-triage-diff で始まるコメントはすべて対象にし、形の検査は
// 関数 parseMarker が行う。形の誤ったマークを、マークでないコメントとして残さないため。
var markerRe = regexp.MustCompile(`<!--(\s*review-triage-diff\b[\s\S]*?)-->`)

var (
	patchRe  = regexp.MustCompile(`^patch run=([0-9]+) problem=(\S+) option=(\S+)$`)
	commitRe = regexp.MustCompile(`^commit ([0-9a-f]{4,40})$`)
	// headEndRe は </head> を大文字と小文字を区別せずに探す。元の文字列に当てるので、見つけた位置で
	// 元の文字列を切れる。strings.ToLower で変えた文字列の位置は、小文字にするとバイト数が変わる文字
	// (ケルビン記号 U+212A など) があると、元の文字列の位置と一致しない
	headEndRe = regexp.MustCompile(`(?i)</head>`)
)

// parseMarker は、コメントの中身 (<!-- と --> の間) をマークとして読む。
func parseMarker(body string) (marker, error) {
	s := strings.TrimSpace(body)
	rest, ok := strings.CutPrefix(s, "review-triage-diff")
	rest = strings.TrimSpace(rest)
	if !ok || rest == "" {
		return marker{}, fmt.Errorf("マークの形が違います: <!--%s-->", body)
	}
	rest = strings.Join(strings.Fields(rest), " ")
	if m := patchRe.FindStringSubmatch(rest); m != nil {
		run, err := strconv.Atoi(m[1])
		if err != nil || run < 1 {
			return marker{}, fmt.Errorf("マークの回番号は 1 以上の整数で書いてください: <!--%s-->", body)
		}
		return marker{kind: "patch", run: run, problem: m[2], option: m[3]}, nil
	}
	if m := commitRe.FindStringSubmatch(rest); m != nil {
		return marker{kind: "commit", sha: m[1]}, nil
	}
	return marker{}, fmt.Errorf("マークの形が違います (patch run=<回番号> problem=<problem_id> option=<ラベル> か commit <SHA>): <!--%s-->", body)
}

// shower は、コミットの差分を返すもの。本番では gitRunner、テストでは偽物を使う。
type shower interface {
	show(sha string) (string, error)
}

type sources struct {
	record *record
	git    shower
}

// styleID は、ツールが入れる <style> の id。既にあれば入れない。
const styleID = "rt-diff-style"

// fill は、HTML のマークをすべて差分の HTML に置き換え、</head> の前に <style> を入れた HTML を返す。
// 1 つでも置き換えられないマークがあれば、すべての理由をまとめてエラーにする。
func fill(html string, src sources) (string, error) {
	var errs []error
	out := markerRe.ReplaceAllStringFunc(html, func(c string) string {
		body := markerRe.FindStringSubmatch(c)[1]
		m, err := parseMarker(body)
		if err != nil {
			errs = append(errs, err)
			return c
		}
		diff, err := src.diff(m)
		if err != nil {
			errs = append(errs, err)
			return c
		}
		return renderDiff(diff)
	})
	if !strings.Contains(out, `id="`+styleID+`"`) {
		loc := headEndRe.FindStringIndex(out)
		if loc == nil {
			errs = append(errs, errors.New("HTML に </head> がありません (色分けの <style> を入れる位置が無い)"))
		} else {
			out = out[:loc[0]] + diffStyle + out[loc[0]:]
		}
	}
	if len(errs) > 0 {
		return "", errors.Join(errs...)
	}
	return out, nil
}

func (s sources) diff(m marker) (string, error) {
	switch m.kind {
	case "patch":
		return s.record.patch(m)
	case "commit":
		return s.git.show(m.sha)
	}
	return "", fmt.Errorf("マークの種類が違います: %s", m.kind)
}
package main

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// gitRunner は、-root のリポジトリで git を実行する。
type gitRunner struct {
	root string
}

// gitTimeout は、git の 1 回の実行に許す時間。git が応答しなくなったときに、ツールが終了しなくなるのを防ぐ。
var gitTimeout = 5 * time.Minute

// show は、コミットの差分 (コミットメッセージを除く) を返す。利用者の git の設定 (diff.external・
// color.ui・diff.noprefix・textconv の設定) で出力の形が変わらないオプションを付ける。設定 core.fsmonitor は
// 打ち消す。打ち消さないと、git がそこに登録したプログラムを起動することがある。
func (g gitRunner) show(sha string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
	defer cancel()
	args := []string{"-C", g.root, "-c", "core.fsmonitor=false",
		"show", "--format=", "--no-ext-diff", "--no-color", "--no-textconv",
		"--src-prefix=a/", "--dst-prefix=b/", sha, "--"}
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.WaitDelay = time.Second
	cmd.Env = gitEnv()
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if ctx.Err() == context.DeadlineExceeded {
		return "", fmt.Errorf("git show %s が %s 以内に終了しませんでした", sha, gitTimeout)
	}
	if err != nil {
		return "", fmt.Errorf("コミット %s の差分を取れません (git show が失敗しました): %s", sha, strings.TrimSpace(stderr.String()))
	}
	return stdout.String(), nil
}

// extraGitEnv は、gitEnv が GIT_ で始まる変数を取り除いた後に足す変数。本番では空で、
// テストがシステムの git の設定を読ませないために使う (取り除く前に設定しても届かないため)。
var extraGitEnv []string

// gitEnv は git に渡す環境を作る。利用者の環境の GIT_ で始まる変数は、リポジトリの場所を替える
// (GIT_DIR・GIT_WORK_TREE など) か、設定を注入する (GIT_CONFIG_PARAMETERS など) ので、-root と違う
// リポジトリや設定を読ませないよう、すべて取り除いてから要るものだけを足す。
func gitEnv() []string {
	var env []string
	for _, kv := range os.Environ() {
		if !strings.HasPrefix(kv, "GIT_") {
			env = append(env, kv)
		}
	}
	env = append(env,
		// コマンド git replace の置き換えを見ない。見ると、記録の SHA と違う内容の差分を出しうる
		"GIT_NO_REPLACE_OBJECTS=1",
		// 認証などで利用者の入力待ちにならない
		"GIT_TERMINAL_PROMPT=0",
	)
	return append(env, extraGitEnv...)
}
package main

import (
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

// record は、記録 YAML のうち、案のパッチを取るのに要る項目だけを読んだもの。様式の SSOT は
// review-triage の record-schema.md。形の検査は triagecheck が行うので、ここでは行わない。
type record struct {
	Runs []struct {
		Plans []struct {
			ProblemID     string `yaml:"problem_id"`
			OptionPatches []struct {
				Option    string `yaml:"option"`
				Patch     string `yaml:"patch"`
				NoChange  bool   `yaml:"no_change"`
				CoveredBy *struct {
					ProblemID string `yaml:"problem_id"`
					Option    string `yaml:"option"`
				} `yaml:"covered_by"`
			} `yaml:"option_patches"`
		} `yaml:"plans"`
	} `yaml:"runs"`
}

func loadRecord(path string) (*record, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	rec, err := parseRecord(data)
	if err != nil {
		return nil, fmt.Errorf("記録 YAML を読めません (%s): %w", path, err)
	}
	return rec, nil
}

func parseRecord(data []byte) (*record, error) {
	var rec record
	if err := yaml.Unmarshal(data, &rec); err != nil {
		return nil, err
	}
	return &rec, nil
}

// patch は、マークが指す案のパッチを返す。
func (r *record) patch(m marker) (string, error) {
	where := fmt.Sprintf("%d 回目の %s の案 %s", m.run, m.problem, m.option)
	if m.run > len(r.Runs) {
		return "", fmt.Errorf("%s: 記録に %d 回目がありません (回は %d 回まで)", where, m.run, len(r.Runs))
	}
	for _, p := range r.Runs[m.run-1].Plans {
		if p.ProblemID != m.problem {
			continue
		}
		for _, o := range p.OptionPatches {
			if o.Option != m.option {
				continue
			}
			switch {
			case o.Patch != "":
				return o.Patch, nil
			case o.NoChange:
				return "", fmt.Errorf("%s: ファイルを変えない案 (no_change) で、パッチがありません", where)
			case o.CoveredBy != nil:
				return "", fmt.Errorf("%s: ほかの問題のパッチで覆う案 (covered_by: %s の案 %s) で、パッチがありません。参照先の節にリンクしてください", where, o.CoveredBy.ProblemID, o.CoveredBy.Option)
			}
			return "", fmt.Errorf("%s: パッチがありません", where)
		}
		return "", fmt.Errorf("%s: option_patches にこの案がありません", where)
	}
	return "", fmt.Errorf("%s: %d 回目の plans に %s がありません", where, m.run, m.problem)
}
package main

import (
	"html"
	"strings"
)

// diffStyle は、差分の色分けに使う <style>。fill が </head> の前に 1 度だけ入れる。
// 日本語の長い 1 行が横に伸びないように、行を折り返す。
const diffStyle = `<style id="` + styleID + `">
.rt-diff { border: 1px solid #d0d7de; border-radius: 6px; margin: 0.5rem 0; overflow: auto; }
.rt-diff pre { margin: 0; padding: 0.5rem 0; font: 12px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
               white-space: pre-wrap; overflow-wrap: anywhere; }
.rt-diff span { display: block; padding: 0 0.75rem; min-height: 1.5em; }
.rt-diff .rt-file { color: #57606a; font-weight: 600; background: #f6f8fa; }
.rt-diff .rt-hunk { color: #0550ae; background: #ddf4ff; }
.rt-diff .rt-add { background: #e6ffec; }
.rt-diff .rt-del { background: #ffebe9; }
.rt-diff .rt-add mark { background: #abf2bc; }
.rt-diff .rt-del mark { background: #ff8182; }
.rt-diff .rt-meta { color: #57606a; }
</style>
`

// diffLine は、差分の 1 行と、その種類 (CSS のクラス名)。
type diffLine struct {
	class string
	text  string
	// mark は、行の中で強調する部分 (text の rune の位置。先頭の +・- を含む)。from == to なら強調しない
	from, to int
}

// renderDiff は、unified diff を、行の種類で色を分けた HTML の断片にする。
func renderDiff(diff string) string {
	lines := classify(diff)
	markPairs(lines)
	var b strings.Builder
	b.WriteString(`<div class="rt-diff"><pre>`)
	for _, l := range lines {
		b.WriteString(`<span class="` + l.class + `">`)
		r := []rune(l.text)
		if l.from < l.to {
			b.WriteString(html.EscapeString(string(r[:l.from])))
			b.WriteString("<mark>" + html.EscapeString(string(r[l.from:l.to])) + "</mark>")
			b.WriteString(html.EscapeString(string(r[l.to:])))
		} else {
			b.WriteString(html.EscapeString(l.text))
		}
		b.WriteString("</span>")
	}
	b.WriteString("</pre></div>")
	return b.String()
}

// classify は、行の種類を決める。diff --git から最初の @@ の前まではファイルの見出しで、
// hunk の中は先頭の 1 文字で決める。hunk の中の --- や +++ で始まる行を見出しとして扱わないため、
// 位置 (見出しの中か hunk の中か) で分ける。
func classify(diff string) []diffLine {
	text := strings.TrimSuffix(diff, "\n")
	if text == "" {
		return nil
	}
	var out []diffLine
	inHunk := false
	for _, s := range strings.Split(text, "\n") {
		class := "rt-file"
		switch {
		case strings.HasPrefix(s, "diff --git "):
			inHunk = false
		case strings.HasPrefix(s, "@@"):
			inHunk = true
			class = "rt-hunk"
		case !inHunk:
		case strings.HasPrefix(s, "+"):
			class = "rt-add"
		case strings.HasPrefix(s, "-"):
			class = "rt-del"
		case strings.HasPrefix(s, `\`):
			class = "rt-meta"
		default:
			class = "rt-ctx"
		}
		out = append(out, diffLine{class: class, text: s})
	}
	return out
}

// markPairs は、続けて並ぶ削除の行と追加の行を先頭から順に 1 つずつ組にし、組の 2 行から先頭と末尾の
// 共通部分を除いた部分を強調の範囲にする。共通部分が無い組は、行全体が変わったので強調しない。
func markPairs(lines []diffLine) {
	for i := 0; i < len(lines); {
		if lines[i].class != "rt-del" {
			i++
			continue
		}
		delStart := i
		for i < len(lines) && lines[i].class == "rt-del" {
			i++
		}
		addStart := i
		for i < len(lines) && lines[i].class == "rt-add" {
			i++
		}
		dels, adds := lines[delStart:addStart], lines[addStart:i]
		for k := 0; k < len(dels) && k < len(adds); k++ {
			markPair(&dels[k], &adds[k])
		}
	}
}

func markPair(del, add *diffLine) {
	a, b := []rune(del.text)[1:], []rune(add.text)[1:]
	p := 0
	for p < len(a) && p < len(b) && a[p] == b[p] {
		p++
	}
	s := 0
	for s < len(a)-p && s < len(b)-p && a[len(a)-1-s] == b[len(b)-1-s] {
		s++
	}
	if p == 0 && s == 0 {
		return
	}
	// 位置は先頭の +・- の 1 文字を含めて数える
	del.from, del.to = 1+p, 1+len(a)-s
	add.from, add.to = 1+p, 1+len(b)-s
}
